package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertThrows;

public class Attribute_setValue_TriageGen2Test {

    @Test
    public void testSetValue_nullParent() {
        // Given
        Attribute attribute = new Attribute("key", "val");

        // When
        String result = attribute.setValue(null);

        // Then
        assertNull(result);
    }

    @Test
    public void testSetValue_notNullParent() {
        // Given
        Attributes parent = new Attributes();
        Attribute attribute = new Attribute("key", "val", parent);

        // When
        String result = attribute.setValue("newVal");

        // Then
        assertEquals("newVal", result);
    }

    @Test
    public void testSetValue_notNullParent_indexNotFound() {
        // Given
        Attributes parent = new Attributes();
        parent.add("otherKey", "otherVal");
        Attribute attribute = new Attribute("key", "val", parent);

        // When
        String result = attribute.setValue("newVal");

        // Then
        assertEquals("val", result);
    }

    @Test
    public void testSetValue_notNullParent_indexFound() {
        // Given
        Attributes parent = new Attributes();
        parent.add("key", "val");
        Attribute attribute = new Attribute("key", "val", parent);

        // When
        String result = attribute.setValue("newVal");

        // Then
        assertEquals("newVal", result);
    }

    @Test
    public void testSetValue_returnOldValue() {
        // Given
        Attributes parent = new Attributes();
        parent.add("key", "oldVal");
        Attribute attribute = new Attribute("key", "val", parent);

        // When
        String result = attribute.setValue("newVal");

        // Then
        assertEquals("oldVal", result);
    }

    @Test
    public void testSetValue_returnOldValue_noParent() {
        // Given
        Attribute attribute = new Attribute("key", "val");

        // When
        String result = attribute.setValue("newVal");

        // Then
        assertEquals("val", result);
    }

    @Test
    public void testSetValue_throwNPE() {
        // Given
        Attribute attribute = new Attribute("key", "val");

        // When
        NullPointerException exception = assertThrows(NullPointerException.class, () -> attribute.setValue(null));

        // Then
        assertSame(exception.getMessage(), "parent");
    }

    @Test
    public void testSetValue_returnOldValue_sameVal() {
        // Given
        Attributes parent = new Attributes();
        Attribute attribute = new Attribute("key", "val", parent);

        // When
        String result = attribute.setValue("val");

        // Then
        assertEquals("val", result);
    }
}
